export function extractSeriesOverview(
  series: string,
  products: AbDesaiATProduct[]
) {
  const seriesItems = products.filter(
    (p) => p.series.toLowerCase() === series.toLowerCase()
  );
  const inStockCount = seriesItems.filter((p) => p.inStock).length;
  const minPrice =
    seriesItems.length > 0
      ? Math.min(...seriesItems.filter((p) => p.priceRs > 0).map((p) => p.priceRs))
      : 0;
  const maxPrice =
    seriesItems.length > 0
      ? Math.max(...seriesItems.map((p) => p.priceRs))
      : 0;

  return {
    series,
    totalCount: seriesItems.length,
    inStockCount,
    minPrice,
    maxPrice,
    items: seriesItems,
  };
}

